//#region Scripts/scheduler/keyboard-navigation/scheduler-kbd-strategy.ts
var SchedulerKbdStrategy = class extends KeyboardNavigationStrategy {
	constructor(scheduler, targetElement, isTransitContainer = false) {
		super(scheduler.getKeyboardNavigator(), targetElement, isTransitContainer);
		this.scheduler = scheduler;
	}
	canSwitchToNestedContentMode() {
		return true;
	}
	getToolbarWrapper() {
		return SchedulerDomUtils.getToolbarWrapper(this.scheduler);
	}
	getVerticalAppointmentsContainer() {
		const apptContainer = SchedulerDomUtils.getVerticalAppointmentsContainer(this.scheduler);
		return apptContainer?.childElementCount > 0 ? apptContainer : null;
	}
	getHorizontalAppointmentsContainer() {
		const apptContainer = SchedulerDomUtils.getHorizontalAppointmentsContainer(this.scheduler);
		return apptContainer?.childElementCount > 0 ? apptContainer : null;
	}
	handleTabKeyDown(evt, allowAltKey = false) {
		if (!allowAltKey && evt.altKey) return false;
		if (evt.shiftKey) {
			if (this.firstItemSelected) return false;
			this.moveToPrevItem();
		} else {
			if (this.lastItemSelected) return false;
			this.moveToNextItem();
		}
		return true;
	}
	initialize() {
		super.initialize();
		this.updateScrollViewerContentFocusability();
	}
	onActiveStateChanged(isActive) {
		super.onActiveStateChanged(isActive);
		this.updateScrollViewerContentFocusability();
	}
	updateScrollViewerContentFocusability() {
		const scrollContent = this.getScrollViewerContent();
		if (!scrollContent) return;
		if (this.navigator.isActive) FocusUtils.removeTabIndex(scrollContent);
		else FocusUtils.makeElementFocusable(scrollContent);
	}
	getScrollViewerContent() {
		return this.scheduler.getScrollViewerContent();
	}
};

//#endregion
//#region Scripts/scheduler/keyboard-navigation/scheduler-hor-appts-kbd-strategy.ts
var SchedulerHorApptsKbdStrategy = class extends SchedulerKbdStrategy {
	constructor(scheduler, targetElement) {
		super(scheduler, targetElement);
		this.itemSelector = `:scope > .${SchedulerCssClasses.HorizontalAppointmentClassName}`;
	}
	queryItems() {
		return this.queryItemsBySelector(this.itemSelector);
	}
	handleKeyDown(evt) {
		const keyCode = import_key.KeyUtils.getEventKeyCode(evt);
		if (keyCode === import_key.KeyCode.Tab) return this.handleTabKeyDown(evt);
		switch (keyCode) {
			case import_key.KeyCode.Enter:
			case import_key.KeyCode.Delete:
			case import_key.KeyCode.Key_n:
			case import_key.KeyCode.Key_r:
				this.performShortcutEvent(evt);
				return true;
		}
		return false;
	}
	handleTabKeyDown(evt) {
		if (!super.handleTabKeyDown(evt, evt.altKey)) return false;
		return true;
	}
	getShortcutContext() {
		return { AppointmentKey: this.selectedItemElement.getAttributeNode("data-key")?.value };
	}
	focusSelectedItem() {
		super.focusSelectedItem();
		this.scheduler.getView()?.syncronizeScrollViewWithHeader();
	}
};

