//#region Scripts/scheduler/keyboard-navigation/scheduler-root-kbd-strategy.ts
var SchedulerRootKbdStrategy = class extends SchedulerKbdStrategy {
	constructor(scheduler) {
		super(scheduler, scheduler);
	}
	queryItems() {
		return new Array(this.getToolbarWrapper(), this.getHorizontalAppointmentsContainer(), this.getVerticalAppointmentsContainer());
	}
	createItemStrategy(itemElement) {
		if (itemElement === this.getToolbarWrapper()) return new SchedulerToolbarContainerKbdStrategy(this.scheduler, itemElement);
		if (itemElement === this.getVerticalAppointmentsContainer()) return new SchedulerVertApptsKbdStrategy(this.scheduler, itemElement);
		if (itemElement === this.getHorizontalAppointmentsContainer()) return new SchedulerHorApptsKbdStrategy(this.scheduler, itemElement);
		throw new Error("Not implemented");
	}
	handleKeyDown(evt) {
		if (import_key.KeyUtils.getEventKeyCode(evt) === import_key.KeyCode.Tab) return this.handleTabKeyDown(evt);
		return false;
	}
	handleTabKeyDown(evt) {
		if (!super.handleTabKeyDown(evt, evt.altKey)) if (evt.shiftKey) this.leaveBackward();
		else this.leaveForward();
		return true;
	}
};

