//#region Scripts/popup/tabbable.ts
const tabbableSelector = [
	"a[href]",
	"audio[controls]",
	"button",
	"[contenteditable]:not([contenteditable=\"false\"])",
	"details>summary:first-of-type",
	"details",
	"input",
	"select",
	"textarea",
	"[tabindex]",
	"video[controls]"
].join(",");
var Tabbable = class Tabbable {
	static getTabbables(element, self) {
		const tabbables = this.findTabbables(element, self);
		const standardOrdered = [];
		const sortByIndex = [];
		tabbables.forEach((tabbable, index) => {
			const tabIndex = Tabbable.getTabIndex(tabbable);
			if (tabIndex === 0) standardOrdered.push(tabbable);
			else sortByIndex.push({
				index,
				tabIndex,
				item: tabbable
			});
		});
		return sortByIndex.sort((a, b) => {
			if (a.tabIndex === b.tabIndex) return a.index - b.index;
			return a.tabIndex - b.tabIndex;
		}).map((x) => x.item).concat(standardOrdered);
	}
	static findTabbables(element, self) {
		const tabbables = Array.from(element.querySelectorAll(tabbableSelector));
		if (self && (element.matches(tabbableSelector) || element.webkitMatchesSelector(tabbableSelector))) tabbables.unshift(element);
		return tabbables.filter(Tabbable.filterTabbable);
	}
	static filterTabbable(element) {
		if (element.disabled) return false;
		if (Tabbable.isHiddenInput(element)) return false;
		if (DomHelper.isHidden(element)) return false;
		if (Tabbable.getTabIndex(element) < 0) return false;
		return true;
	}
	static getTabIndex(element) {
		const tabIndexAttr = element.getAttribute("tabindex");
		if (tabIndexAttr) {
			const tabIndex = parseInt(tabIndexAttr, 10);
			if (!isNaN(tabIndex)) return tabIndex;
		}
		if (element.contentEditable === "true") return 0;
		if (element.nodeName === Tags.audio || element.nodeName === Tags.video || element.nodeName === Tags.details) return 0;
		return element.tabIndex;
	}
	static isHiddenInput(element) {
		return element.tagName === Tags.input && element.getAttribute("type") === InputType.hidden;
	}
};

//#endregion
//#region Scripts/scheduler/keyboard-navigation/scheduler-date-navigator-kbd-strategy.ts
var SchedulerDateNavigatorKbdStrategy = class extends KeyboardNavigationStrategy {
	constructor(dateNavigator, targetElement) {
		super(dateNavigator.getKeyboardNavigator(), targetElement, true);
		this._dateNavigator = dateNavigator;
	}
	canSwitchToNestedContentMode() {
		return true;
	}
	leaveTransitContainer(direction) {
		const calendar = this._dateNavigator.getCalendar();
		if (calendar) {
			const tabbableElements = Tabbable.getTabbables(calendar, false);
			if (!tabbableElements.length || direction === 0) return;
			const focusedElement = direction === 2 ? tabbableElements[0] : tabbableElements[tabbableElements.length - 1];
			FocusUtils.focusElement(focusedElement);
		}
	}
};

